#include <bits/stdc++.h>
using namespace std;

bool isPalindrome(const string& s) {
    int left = 0, right = (int)s.size() - 1;
    while (left < right) {
        if (s[left] != s[right]) return false;
        left++; right--;
    }
    return true;
}

bool validPalindrome(string s) {
    if (isPalindrome(s)) return true;
    for (int i = 0; i < (int)s.size(); i++) {
        string candidate = s.substr(0, i) + s.substr(i + 1);          // remove one character and rebuild
        if (isPalindrome(candidate)) return true;
    }
    return false;
}

int main() {
    string s = "abca";
    cout << (validPalindrome(s) ? "true" : "false") << endl;
    return 0;
}

